// Source of truth for DevAtlas's 18 starter prompts. Both
// scripts/seed-prompts.ts (upserts via supabase-js) and
// supabase/seed/prompts.sql (generated by scripts/generate-seed-sql.ts,
// for `supabase db reset`) read from this file so the two never drift.
//
// Review rubric applied to every entry below: placeholders are bracketed
// consistently ([LIKE THIS]), expected_output_notes is specific enough to
// catch a lazy AI response, and tags are drawn from a shared, reused pool
// rather than one-off per prompt.

export interface SeedPrompt {
  title: string;
  slug: string;
  description: string;
  category: "new_app" | "module_feature" | "debugging" | "frontend" | "backend";
  tags: string[];
  base_instructions: string;
  fill_in_details_guidance: string;
  reference_projects_guidance: string;
  reference_links_guidance: string;
  expected_output_notes: string;
}

